
const D={"type": "עור בוגר", "profile": "שלב טבעי מגיל 40–45: ייצור הקולגן, האלסטין והחומצה ההיאלורונית מואט, מחסום הלחות נחלש, ומופיעים קמטוטים, כתמים, חספוס ואובדן זוהר.", "needs": "תמיכה בתהליכי תיקון — רכיבים משקמים, נוגדי חמצון, שומנים איכותיים, מרככים עמוקים ולחות פעילה לרכות, גמישות ובהירות.", "routine": {"בוקר": "ניקוי עדין (סבון רך או מים), מי פנים עשירים, קרם יום מזין. בימים יבשים אפשר לשלב סרום לפני הקרם.", "ערב": "הסרת איפור בשמן מותאם, שטיפה עדינה, מי פנים מרגיעים, סרום שמנים עשיר ולחות משלימה.", "פעם-פעמיים בשבוע": "פילינג גרגרים עדין בלילה ואחריו מסיכת חימר לבן שיקומית, ולסיום מי פנים וקרם עשיר ללילה."}, "products": [["מסיר איפור שומני", "על בסיס שמן שקדים ושמן גזר — ממיס איפור ולכלוך בעדינות ומזין את העור."], ["שמן הידרופילי", "תכשיר ניקוי שומני שנשטף במים, מנקה לעומק בלי תחושת שומניות."], ["פילינג גרגרים", "פילינג רך ומכבד רגישות — מסיר תאים מתים, מבהיר בעדינות ומחייה את המרקם."], ["מסיכת חימר", "מסיכת אנטי-אייג'ינג רכה מחימר לבן עם תה ירוק, פנינים ורימונים — ממריצה בלי לייבש."], ["מי פנים", "משלבים חומצה היאלורונית ואקסטרקטים עשירים — הרגעה, לחות מיידית ותמיכה בשיקום."], ["קרם יום", "קרם שכבות — לחות מבפנים, הזנה שומנית מבחוץ ונוגדי חמצון חזקים לתיקון נזקים מצטברים."], ["סרום שמנים", "שמנים עמוקים ומשקמים (רוז היפ, נר הלילה, רימונים) עם פצ'ולי, גרניום וסנדלווד — האטת סימני גיל."]], "shop": [["שמן שקדים מתוקים", "שמן נשא עדין ורב-שימושי לכל סוגי העור. מרכך, מזין ובסיס מצוין למסירי איפור, שמני ניקוי וסרומים."], ["שמן גזר", "עשיר בבטא-קרוטן ונוגדי חמצון. מחיה ומחדש עור עייף ותומך במראה זוהר ואחיד."], ["ויטמין E", "נוגד חמצון מסיס בשמן — מגן על הפורמולה מהתחמצנות ומזין את העור."], ["פוליסורבט 80", "מתחלב עדין שמאפשר לשמן להישטף במים. הבסיס לשמן הידרופילי שנשטף נקי."], ["קרם בסיס", "בסיס מוכן (מים+שמן+מתחלב) שמשביחים לפי הצורך — חוסך הכנת קרם מאפס."], ["הידרוסול ורדים", "מי פרחים עדינים, אנטי-דלקתיים ומרגיעים. תורמים ללחות ולניחוח, בסיס למי פנים ותחליבים."], ["חימר לבן", "חימר עדין ורך שמנקה ומרכך בלי לייבש — מתאים לעור יבש, רגיל ורגיש."], ["אקסטרקט תה ירוק", "נוגד חמצון רב-עוצמה, מרגיע ומגן מפני נזקי סביבה — מצוין לעור בוגר."], ["אבקת פנינים", "מקור למינרלים וחומצות אמינו, מבהיר ומחיה את מראה העור."], ["אקסטרקט מנגו", "מזין, עשיר בוויטמינים ותורם לרכות וללחות."], ["אקסטרקט מלפפונים", "מרגיע ומצנן, מלחלח ותורם למראה רענן ונינוח."], ["אקסטרקט רימונים", "עשיר בנוגדי חמצון (פוליפנולים), תומך בחידוש ובמראה קורן."], ["גלעיני משמש טחונים", "גרגרי פילינג עדינים וקטנים לניקוי מכני של תאי עור מתים בלי לשרוט."], ["שמן זרעי רימונים", "עשיר בחומצה פוניצית ונוגדי חמצון — משקם, מחזק ותומך בעור בוגר."], ["שמן רוז היפ", "עשיר ברטינואידים טבעיים, נוגדי חמצון וחומצות שומן — מחדש עור ומשפר קמטוטים."], ["שמן נר הלילה", "עשיר בחומצת גמא-לינולנית (GLA) — מאזן, מרגיע ותומך בעור מעורב ובוגר."], ["שמן זרעי מלפפונים", "שמן קליל ומאזן, עשיר בנוגדי חמצון — מרענן ולא מכביד."], ["סקוולאן צמחי", "ליפיד קליל הדומה לשומן הטבעי של העור — נספג מהר ומעניק רכות בלי כובד."], ["גליצרין צמחי", "מושך לחות אל העור ושומר עליה — רכיב בסיס בתכשירי לחות."], ["אסקורביל פלמיטט", "נגזרת ויטמין C מסיסת שמן, נוגדת חמצון ותומכת בזוהר ובגוון אחיד."], ["חומצה היאלורונית", "מולקולת לחות רבת-עוצמה שקושרת מים בעור ומעניקה אפקט מילוי ורכות."], ["תמצית אתרי ורד בחוחובה", "שמן ורד מדולל בחוחובה — אנטי-דלקתי, מאיץ חידוש תאים ומחזיר זוהר לעור בוגר."], ["תמצית אתרי גרניום", "מאזן, אנטיספטי ומחזיר זוהר. משתלב יפה בפורמולות פנים."], ["תמצית אתרי פצ'ולי", "מזרז חידוש תאים ומתאים לעור יבש, סדוק ובוגר."], ["תמצית אתרי סנדלווד", "מרגיע עמוק, תומך בהתחדשות ומעניק ניחוח מעוגן וחם."], ["תמצית אתרי תפוז", "מרענן, ממריץ ומחיה עור עייף, עם ניחוח נעים ומרומם."]]};
